\section{\texorpdfstring{$\text{\sffamily\upshape\fontseries{sb}\selectfont ZPP}\not\subseteq\text{\sffamily\upshape\fontseries{sb}\selectfont psP}$}{ZPP is not in psP}} \label{sec:zpp-psp}

We prove \autoref{thm:zpp-psp}. For $z\in\{0,1\}^n$, let $|z|$ be $z$'s weight (number of $1$s), and let $z_\leftarrow=z_1\cdots z_{n/2}$ and $z_\rightarrow=z_{n/2+1}\cdots z_n$ be $z$'s left and right halves. Define $f\colon\{0,1\}^n\to\{0,1,\bot\}$ by: \[f(z)~=~\begin{cases}1&\text{if $|z_\rightarrow|\ge n/3$~\,and~\,$|z_\leftarrow|=0$}\\0&\text{if $|z_\leftarrow|\ge n/3$~\,and~\,$|z_\rightarrow|=0$}\end{cases}\] With the setup from \autoref{sec:approach:lifting}, define $F\colon S^n\to\{0,1,\bot\}$ by $F(x,y)=f(g^n(x,y))$.

$F\in\ZPP$: We have $F\in\RP$ by the randomized protocol that picks a uniformly random $i\in\{n/2+1,\ldots,n\}$ and computes and outputs $g(x_i,y_i)$. We have $\overline{F}\in\RP$ by the randomized protocol that picks a uniformly random $i\in\{1,\ldots,n/2\}$ and computes and outputs $g(x_i,y_i)$.

$F\not\in\psP$: Suppose for contradiction that some total function $F'\colon S^n\to\{0,1\}$ that agrees with $F$ has a randomized protocol $D$ of cost $d=0.01\sqrt{n}$ that's been amplified to have two-sided error probability $0.01$ instead of $1/3$. Let $F_1=F^{-1}(1)$ and $F_0=F^{-1}(0)$ and $F'_\sus{1}=F^{\prime-1}(1)$ and $F'_\sus{0}=F^{\prime-1}(0)$. Let $z=0^n$ and assume $|F'_\sus{1}\cap S^n_\sus{z}|\ge 0.5|S^n_\sus{z}|$. A symmetric argument handles the case $|F'_\sus{0}\cap S^n_\sus{z}|\ge 0.5|S^n_\sus{z}|$.

We describe a process that iteratively updates $z\in\{0,1\}^n$, a structure $(a,b,c)$ of width $w$, a rectangle $R\subseteq S^n$, and $k\ge 0$, maintaining these invariants: \[|z_\rightarrow|=0\hspace*{0.6cm}\text{$z$ agrees with $c$}\hspace*{0.6cm}\text{$R$ is $(a,b,c)$-balanced}\hspace*{0.6cm}|R_z|\ge 2^{-k}|S^{a,b}_\sus{z}|\hspace*{0.6cm}|F'_\sus{1}\cap R_z|\ge 0.5|R_z|\] Initially, $z=0^n$, $(a,b,c)$ is all $*$s, $w=0$, $R=S^n$, and $k=0$. Each iteration extends $(a,b,c)$ and shrinks $R$ to a subrectangle. Each iteration is either \emph{safe}, in which case $\sqrt{n}$ many $0$s flip to $1$s in $z_\leftarrow$ and $k$ increases by $\le d+13$, or \emph{unsafe}, in which case $z$ doesn't change and $k$ decreases by $\ge(\text{increase in $w$})/2>0$. This continues until $|z_\leftarrow|\ge n/3$, in other words, $(n/3)/\sqrt{n}=\sqrt{n}/3$ safe iterations. Thus at the end, we have $f(z)=0$ and therefore $R_z\subseteq F_0\subseteq F'_\sus{0}$, contradicting the invariant $|F'_\sus{1}\cap R_z|\ge 0.5|R_z|>0$. Since the safe iterations increase $k$ by $\le(d+13)\sqrt{n}/3$ in total, and the unsafe iterations decrease $k$ by $\ge w/2$ in total, and since $k\ge 0$, we always have $w/2\le(d+13)\sqrt{n}/3$, which implies $w\le 0.02n$ since $d=0.01\sqrt{n}$.

We now describe an iteration. Since $c_i\ne *$ for $\le w\le 0.02n$ many $i\le n/2$, and $z_i=1$ for $\le n/3+\sqrt{n}$ many $i\le n/2$, we have $c_i=*$ and $z_i=0$ for $\ge n/2-0.02n-(n/3+\sqrt{n})\ge 0.1n$ many $i\le n/2$. Let $\calI$ be the set of all sets $I\subseteq\bracescolon{i\le n/2}{\text{$c_i=*$ and $z_i=0$}}$ with $|I|=\sqrt{n}$.

Since $D$ is a $0.01$-error randomized protocol for $F'$, there exists a deterministic protocol $P$ in the support of $D$ such that $P(x,y)\ne F'(x,y)$ with probability $\le 0.01$ over $(x,y)$ sampled from the uniform mixture of the uniform distribution over $R_z$ and the uniform distribution over $R_\sus{z^\calI}$. Hence $P(x,y)\ne F'(x,y)$ for $\le 0.02|R_z|$ many $(x,y)\in R_z$ and for $\le 0.02|R_\sus{z^\calI}|$ many $(x,y)\in R_\sus{z^\calI}$. Let $P_1=P^{-1}(1)$ and $P_0=P^{-1}(0)$. Since $P$ has depth $d$, $P_1\cap R$ is partitioned into at most $2^d$ rectangles $R^1,R^2,R^3,\ldots{}$. Say $\ell$ is \emph{major} if $|R^\ell_\sus{z}|\ge 2^{-(d+4)}|R_z|$ and \emph{minor} otherwise. For each major $\ell$, we have $|R^\ell_\sus{z}|\ge 2^{-(k+d+4)}|S^{a,b}_\sus{z}|$, so by \autoref{lem:packing} (applied to the projections of $R^\ell$ and $z$ to the $*$ coordinates, with $m=n-w$), there exists a set $\calQ^\ell$ of pairwise disjoint subrectangles of $R^\ell$ such that $\sum_\sus{Q\in\calQ^\ell}|Q_z|\ge 0.99|R^\ell_\sus{z}|$ and for each $Q\in\calQ^\ell$ there exists a structure $(a',b',c')$ of width $w'$ extending $(a,b,c)$ such that $z$ agrees with $c'$, $Q$ is $(a',b',c')$-balanced, and $|Q_z|\ge 2^{-((k+d+4)+8-(w'-w))}|S^{a',b'}_\sus{z}|$. We have
\begin{align*}
\textstyle|F'_\sus{1}\cap P_0\cap R_z|~&\textstyle\le~0.02|R_z|\\
\textstyle\sum_{\text{minor }\ell}|R^\ell_\sus{z}|~&\textstyle\le~2^d\cdot 2^{-(d+4)}|R_z|~\le~0.07|R_z|\\
\textstyle\sum_{\text{major }\ell}\bigparens{|R^\ell_\sus{z}|-\sum_\sus{Q\in\calQ^\ell}|Q_z|}~&\textstyle\le~\sum_{\text{major }\ell}0.01|R^\ell_\sus{z}|~\le~0.01|R_z|
\end{align*}
and thus, letting $\calQ=\bigcup_{\text{major }\ell}\calQ^\ell$:
\begin{align*}
\textstyle\sum_{Q\in\calQ}|Q_z|~&\textstyle=~|(F'_\sus{1}\cup P_1)\cap R_z|-|F'_\sus{1}\cap P_0\cap R_z|-\sum_{\text{minor }\ell}|R^\ell_\sus{z}|-\sum_{\text{major }\ell}\bigparens{|R^\ell_\sus{z}|-\sum_\sus{Q\in\calQ^\ell}|Q_z|}\\
&\textstyle\ge~0.5|R_z|-0.02|R_z|-0.07|R_z|-0.01|R_z|\\
&\textstyle=~0.4|R_z|
\end{align*}
Say $Q\in\calQ$ is \emph{good} if $w'-w\le 3d$ (for the $w'$ associated with $Q$) and \emph{bad} otherwise. This iteration is \emph{safe} if $\sum_{\text{good }Q\in\calQ}|Q_z|\ge 0.2|R_z|$ and \emph{unsafe} otherwise, in which case $\sum_{\text{bad }Q\in\calQ}|Q_z|\ge 0.2|R_z|$.

\paragraph{Unsafe iteration:} We have \[\textstyle\sum_{\text{bad }Q\in\calQ}|F'_\sus{0}\cap Q_z|~\le~|F'_\sus{0}\cap P_1\cap R_z|~\le~0.02|R_z|~\le~0.1\sum_{\text{bad }Q\in\calQ}|Q_z|\] so there exists a bad $Q\in\calQ$ with associated $(a',b',c')$ and $w'$ such that $|F'_\sus{0}\cap Q_z|\le 0.1|Q_z|\le 0.5|Q_z|$, so $|F'_\sus{1}\cap Q_z|\ge 0.5|Q_z|$. We conclude the iteration by updating $(a,b,c)\leftarrow(a',b',c')$ and $w\leftarrow w'$ and $R\leftarrow Q$ and $k\leftarrow k+d+12-(w'-w)$. The invariants are maintained. As we wanted for an unsafe iteration, $z$ doesn't change and $k$ decreases by $(\text{increase in $w$})-d-12\ge(\text{increase in $w$})/2$ since $(\text{increase in $w$})>3d$ since $Q$ is bad.

\paragraph{Safe iteration:} For each good $Q\in\calQ$ with associated $(a',b',c')$ and $w'$, if we sample a uniformly random $I\in\calI$ and a uniformly random permutation of $I$'s elements, then{\allowdisplaybreaks
\begin{align*}
\textstyle\Pr[\text{$z^I$ doesn't agree with $c'$}]~&\textstyle=~\Pr\bigbrackets{(\exists i\in I):~c'_\sus{i}=0}\\*
&\textstyle=~\Pr\bigbrackets{(\exists i\,:\,\text{$c_i=*$ and $c'_\sus{i}=0$})~(\exists e\in[\sqrt{n}]):~\text{$I$'s $e$th element is $i$}}\\
&\textstyle\le~\sum_\sus{i\,:\,c_i=*\text{ and }c'_\sus{i}=0}\sum_\sus{e\in[\sqrt{n}]}\Pr[\text{$I$'s $e$th element is $i$}]\\
&\textstyle\le~(w'-w)\cdot\sqrt{n}\cdot 1/0.1n\\
&\textstyle\le~3d\cdot 10/\sqrt{n}\\*
&\textstyle=~0.3
\end{align*}
}since $I$'s $e$th element is uniformly distributed over a set of $\ge 0.1n$ many $i$, and since $w'-w\le 3d$ since $Q$ is good. If $z^I$ agrees with $c'$, then $|Q_\sus{z^I}|\ge 0.99|Q|/2^{n-w'}\ge 0.98|Q_z|$ since $z$ agrees with $c'$ and $Q$ is $(a',b',c')$-balanced. Thus: \[\textstyle|Q_\sus{z^\calI}|~=~\sum_{I\in\calI}|Q_\sus{z^I}|~\ge~\sum_\sus{I\in\calI\,:\,z^I\text{ agrees with }c'}|Q_\sus{z^I}|~\ge~0.7|\calI|\cdot 0.98|Q_z|~\ge~0.6|\calI|\cdot|Q_z|\] It follows that: \[\textstyle\sum_{\text{good }Q\in\calQ}|Q_\sus{z^\calI}|~\ge~0.6|\calI|\sum_{\text{good }Q\in\calQ}|Q_z|~\ge~0.6|\calI|\cdot 0.2|R_z|~=~0.12|\calI|\cdot|R_z|\] We have $|R_z|\ge 0.99|R|/2^{n-w}\ge 0.98|R_\sus{z^I}|$ for each $I\in\calI$ since $z$ and $z^I$ agree with $c$ and $R$ is $(a,b,c)$-balanced, so: \[\textstyle|R_z|~\ge~0.98\sum_{I\in\calI}|R_\sus{z^I}|/|\calI|~=~0.98|R_\sus{z^\calI}|/|\calI|\] It follows that: \[\textstyle\sum_{\text{good }Q\in\calQ}|Q_\sus{z^\calI}|~\ge~0.12|\calI|\cdot|R_z|~\ge~0.12\cdot 0.98|R_\sus{z^\calI}|~\ge~0.1|R_\sus{z^\calI}|\] We have \[\textstyle\sum_{\text{good }Q\in\calQ}|F'_\sus{0}\cap Q_\sus{z^\calI}|~\le~|F'_\sus{0}\cap P_1\cap R_\sus{z^\calI}|~\le~0.02|R_\sus{z^\calI}|~\le~0.2\sum_{\text{good }Q\in\calQ}|Q_\sus{z^\calI}|\] so there exists a good $Q\in\calQ$ with associated $(a',b',c')$ and $w'$ such that $|F'_\sus{0}\cap Q_\sus{z^\calI}|\le 0.2|Q_\sus{z^\calI}|\le 0.5|Q_\sus{z^\calI}|$, so $|F'_\sus{1}\cap Q_\sus{z^\calI}|\ge 0.5|Q_\sus{z^\calI}|$. Hence there exists an $I\in\calI$ such that $|F'_\sus{1}\cap Q_\sus{z^I}|\ge 0.5|Q_\sus{z^I}|$ and $z^I$ agrees with $c'$ (since $Q_\sus{z^I}=\emptyset$ if $z^I$ doesn't agree with $c'$). Also: \[\textstyle|Q_\sus{z^I}|~\ge~0.98|Q_z|~\ge~0.98\cdot 2^{-(k+d+12)}|S^{a',b'}_\sus{z}|~\ge~0.98\cdot 2^{-(k+d+12)}\cdot 0.98|S^{a',b'}_\sus{\raisebox{-1.5pt}{\scriptsize $z^I$}}|~\ge~2^{-(k+d+13)}|S^{a',b'}_\sus{\raisebox{-1.5pt}{\scriptsize $z^I$}}|\] We conclude the iteration by updating $z\leftarrow z^I$ and $(a,b,c)\leftarrow (a',b',c')$ and $w\leftarrow w'$ and $R\leftarrow Q$ and $k\leftarrow k+d+13$. The invariants are maintained. As we wanted for a safe iteration, $\sqrt{n}$ many $0$s flip to $1$s in $z_\leftarrow$ and $k$ increases by $\le d+13$.

\section{\texorpdfstring{$\text{\sffamily\upshape\fontseries{sb}\selectfont MA}\not\subseteq\text{\sffamily\upshape\fontseries{sb}\selectfont NP}^\text{\sffamily\upshape\fontseries{sb}\selectfont BPP}$}{MA is not in NP\textasciicircum BPP}} \label{sec:ma-np-bpp}

We prove \autoref{thm:ma-np-bpp}. For $z\in\{0,1\}^n$, let $|z|$ be $z$'s weight (number of $1$s), and let $z_\leftarrow=z_1\cdots z_{n/2}$ and $z_\rightarrow=z_{n/2+1}\cdots z_n$ be $z$'s left and right halves. Define $f\colon\{0,1\}^n\to\{0,1,\bot\}$ by: \[f(z)~=~\begin{cases}1&\text{if $|z_\leftarrow|=n/2$~\,\mywidthboxc{and}{or}~\,$|z_\rightarrow|>0$}\\0&\text{if $|z_\leftarrow|\le n/6$~\,and~\,$|z_\rightarrow|=0$}\end{cases}\] With the setup from \autoref{sec:approach:lifting}, define $F\colon S^n\to\{0,1,\bot\}$ by $F(x,y)=f(g^n(x,y))$.

$F\in\MA$: Consider the randomized protocol that picks a uniformly random $i\in\{1,\ldots,n/2\}$ and computes and outputs $g(x_i,y_i)$, and for each $i\in\{n/2+1,\ldots,n\}$ consider the deterministic protocol that computes and outputs $g(x_i,y_i)$. This set of $n/2+1$ protocols is an $\MA$-type protocol of cost $O(\log n)$ for $F$: If $F(x,y)=1$ then at least one of these protocols outputs $1$ with probability $1\ge 2/3$, and if $F(x,y)=0$ then each of these protocols outputs $1$ with probability $\le 1/3$.

$F\not\in\NP^\BPP=\N\bigcdot\BPP$: Suppose for contradiction $F$ has an $\N\bigcdot\BPP$-type protocol $\calD$ of cost $d=0.01\sqrt{n}$ where the $\BPP$ part has been amplified to have error probability $0.01$ instead of $1/3$. The proof has a \emph{preprocessing phase} and an \emph{iterative phase}. For $z_\leftarrow$, we use the notation $i$, $I$, $\calI$ for indices, sets of indices, and sets of sets of indices. For $z_\rightarrow$, we use the notation $j$, $J$, $\calJ$ for indices, sets of indices, and sets of sets of indices.

\paragraph{Preprocessing phase:} For $z=1^{n/2}0^{n/2}$ we have $f(z)=1$, so $F(x,y)=1$ for all $(x,y)\in S^n_\sus{z}$. Since $|\calD|\le 2^d$, there exists a $D\in\calD$ such that $D(x,y)\ge 0.99$ for $\ge 2^{-d}|S^n_\sus{z}|$ many $(x,y)\in S^n_\sus{z}$. Define $F'$ to have the same valid inputs as $F$, and such that $D$ is a $0.01$-error randomized protocol for $F'$. Let $F_1=F^{-1}(1)$ and $F_0=F^{-1}(0)$ and $F'_\sus{1}=F^{\prime-1}(1)$ and $F'_\sus{0}=F^{\prime-1}(0)$. Thus $|F'_\sus{1}\cap S^n_\sus{z}|\ge 2^{-d}|S^n_\sus{z}|$ and $F_1\subseteq F'_\sus{1}\cup F'_\sus{0}$ and $F_0\subseteq F'_\sus{0}$.

Let $D'$ be the further amplified version of $D$ that outputs the majority vote of $2d$ independent runs of $D$, so $D'$ is a $0.01\cdot 2^{-d}$-error randomized protocol for $F'$ of cost $2d^2$. There exists a deterministic protocol $P$ in the support of $D'$ such that $P(x,y)\ne F'(x,y)$ with probability $\le 0.01\cdot 2^{-d}$ over $(x,y)$ sampled from the uniform mixture of the uniform distribution over $S^n_\sus{z}$ and the uniform distribution over $S^n_\sus{z^\calJ}$ where $\calJ=\bigbraces{\{n/2+1\},\ldots,\{n\}}$, noting that $S^n_\sus{z}\cup S^n_\sus{z^\calJ}\subseteq F_1\subseteq F'_\sus{1}\cup F'_\sus{0}$. Hence $P(x,y)\ne F'(x,y)$ for $\le 0.02\cdot 2^{-d}|S^n_\sus{z}|$ many $(x,y)\in S^n_\sus{z}$ and for $\le 0.02\cdot 2^{-d}|S^n_\sus{z^\calJ}|$ many $(x,y)\in S^n_\sus{z^\calJ}$. Let $P_1=P^{-1}(1)$ and $P_0=P^{-1}(0)$. Since $P$ has depth $2d^2$, $P_1$ is partitioned into at most $2^{2d^2}$ rectangles $R^1,R^2,R^3,\ldots{}$. Say $\ell$ is \emph{major} if $|R^\ell_\sus{z}|\ge 2^{-(d+2d^2+4)}|S^n_\sus{z}|$ and \emph{minor} otherwise. For each major $\ell$, by \autoref{lem:packing} (with $m=n$), there exists a set $\calQ^\ell$ of pairwise disjoint subrectangles of $R^\ell$ such that $\sum_\sus{Q\in\calQ^\ell}|Q_z|\ge 0.99|R^\ell_\sus{z}|$ and for each $Q\in\calQ^\ell$ there exists a structure $(a,b,c)$ of width $w\le d+2d^2+12\le 0.01n$ such that $z$ agrees with $c$, $Q$ is $(a,b,c)$-balanced, and $|Q_z|\ge 2^{-(d+2d^2+12-w)}|S^{a,b}_\sus{z}|$. We have
\begin{align*}
\textstyle|F'_\sus{1}\cap P_0\cap S^n_\sus{z}|~&\textstyle\le~0.02\cdot 2^{-d}|S^n_\sus{z}|~\le~0.02|F'_\sus{1}\cap S^n_\sus{z}|\\
\textstyle\sum_{\text{minor }\ell}|R^\ell_\sus{z}|~&\textstyle\le~2^{2d^2}\cdot 2^{-(d+2d^2+4)}|S^n_\sus{z}|~\le~0.07\cdot 2^{-d}|S^n_\sus{z}|~\le~0.07|F'_\sus{1}\cap S^n_\sus{z}|\\
\textstyle\sum_{\text{major }\ell}\bigparens{|R^\ell_\sus{z}|-\sum_\sus{Q\in\calQ^\ell}|Q_z|}~&\textstyle\le~\sum_{\text{major }\ell}0.01|R^\ell_\sus{z}|~\le~0.01|P_1\cap S^n_\sus{z}|
\end{align*}
and thus, letting $\calQ=\bigcup_{\text{major }\ell}\calQ^\ell$:
\begin{align*}
\textstyle\sum_{Q\in\calQ}|Q_z|~&\textstyle=~|(F'_\sus{1}\cup P_1)\cap S^n_\sus{z}|-|F'_\sus{1}\cap P_0\cap S^n_\sus{z}|-\sum_{\text{minor }\ell}|R^\ell_\sus{z}|-\sum_{\text{major }\ell}\bigparens{|R^\ell_\sus{z}|-\sum_\sus{Q\in\calQ^\ell}|Q_z|}\\
&\textstyle\ge~|(F'_\sus{1}\cup P_1)\cap S^n_\sus{z}|(1-0.02-0.07-0.01)\\
&\textstyle\ge~0.9|F'_\sus{1}\cap S^n_\sus{z}|\\
&\textstyle\ge~0.9\cdot 2^{-d}|S^n_\sus{z}|
\end{align*}
For each $Q\in\calQ$ with associated $(a,b,c)$ and $w$, and for $J=\{j\}\in\calJ$, $z^J$ agrees with $c$ iff $c_j=*$, which holds for $\ge n/2-w\ge 0.98|\calJ|$ many $J\in\calJ$. If $z^J$ agrees with $c$, then $|Q_\sus{z^J}|\ge 0.99|Q|/2^{n-w}\ge 0.98|Q_z|$ since $z$ agrees with $c$ and $Q$ is $(a,b,c)$-balanced. Thus: \[\textstyle|Q_\sus{z^\calJ}|~=~\sum_{J\in\calJ}|Q_\sus{z^J}|~\ge~\sum_\sus{J\in\calJ\,:\,z^J\text{ agrees with }c}|Q_\sus{z^J}|~\ge~0.98|\calJ|\cdot 0.98|Q_z|~\ge~0.9|\calJ|\cdot|Q_z|\] It follows that: \[\textstyle\sum_{Q\in\calQ}|Q_\sus{z^\calJ}|~\ge~0.9|\calJ|\sum_{Q\in\calQ}|Q_z|~\ge~0.9|\calJ|\cdot 0.9\cdot 2^{-d}|S^n_\sus{z}|~\ge~0.8|\calJ|\cdot 2^{-d}|S^n_\sus{z}|\] We have $|S^n_\sus{z}|\ge 0.99|S^n|/2^n\ge 0.98|S^n_\sus{z^J}|$ for each $J\in\calJ$ since $S^n$ is balanced, so: \[\textstyle|S^n_\sus{z}|~\ge~0.98\sum_{J\in\calJ}|S^n_\sus{z^J}|/|\calJ|~=~0.98|S^n_\sus{z^\calJ}|/|\calJ|\] It follows that: \[\textstyle\sum_{Q\in\calQ}|Q_\sus{z^\calJ}|~\ge~0.8|\calJ|\cdot 2^{-d}|S^n_\sus{z}|~\ge~0.8\cdot 2^{-d}\cdot 0.98|S^n_\sus{z^\calJ}|~\ge~0.7\cdot 2^{-d}|S^n_\sus{z^\calJ}|\] We have \[\textstyle\sum_{Q\in\calQ}|F'_\sus{0}\cap Q_\sus{z^\calJ}|~\le~|F'_\sus{0}\cap P_1\cap S^n_\sus{z^\calJ}|~\le~0.02\cdot 2^{-d}|S^n_\sus{z^\calJ}|~\le~0.03\sum_{Q\in\calQ}|Q_\sus{z^\calJ}|\] so there exists a $Q\in\calQ$ such that $|F'_\sus{0}\cap Q_\sus{z^\calJ}|\le 0.03|Q_\sus{z^\calJ}|\le 0.3|Q_\sus{z^\calJ}|$, so $|F'_\sus{1}\cap Q_\sus{z^\calJ}|\ge 0.7|Q_\sus{z^\calJ}|$. Define $R$ to be this $Q$, with associated $(a,b,c)$ and $w$, and redefine $\calJ=\bigbracescolon{\{j\}}{\text{$j>n/2$ and $c_j=*$}}$, which doesn't change $R_\sus{z^\calJ}$ since $R$ is $(a,b,c)$-balanced. In summary, letting $k=3d^2-w$: \[\textstyle z=1^{n/2}0^{n/2}\hspace*{0.6cm}\text{$z$ agrees with $c$}\hspace*{0.6cm}\text{$R$ is $(a,b,c)$-balanced}\hspace*{0.6cm}|R_z|\ge 2^{-k}|S^{a,b}_\sus{z}|\hspace*{0.6cm}|F'_\sus{1}\cap R_\sus{z^\calJ}|\ge 0.7|R_\sus{z^\calJ}|\]

\paragraph{Iterative phase:} We describe a process that iteratively updates $z\in\{0,1\}^n$, a structure $(a,b,c)$ of width $w$, a rectangle $R\subseteq S^n$, and $k\ge 0$, maintaining these invariants, where $\calJ=\bigbracescolon{\{j\}}{\text{$j>n/2$ and $c_j=*$}}$: \[|z_\rightarrow|=0\hspace*{0.6cm}\text{$z$ agrees with $c$}\hspace*{0.6cm}\text{$R$ is $(a,b,c)$-balanced}\hspace*{0.6cm}|R_z|\ge 2^{-k}|S^{a,b}_\sus{z}|\hspace*{0.6cm}|F'_\sus{1}\cap R_\sus{z^\calJ}|\ge 0.7|R_\sus{z^\calJ}|\] The initial $z=1^{n/2}0^{n/2}$, $(a,b,c)$, $w$, $R$, and $k=3d^2-w$ are from the end of the preprocessing phase. Each iteration extends $(a,b,c)$ and shrinks $R$ to a subrectangle. Each iteration is either \emph{safe}, in which case $\sqrt{n}$ many $1$s flip to $0$s in $z_\leftarrow$ and $k$ increases by $\le d+13$, or \emph{unsafe}, in which case $z$ doesn't change and $k$ decreases by $\ge(\text{increase in $w$})/2>0$. This continues until $|z_\leftarrow|\le n/6$, in other words $(n/3)/\sqrt{n}=\sqrt{n}/3$ safe iterations. Thus at the end, we have $f(z)=0$ and therefore $R_z\subseteq F_0\subseteq F'_\sus{0}$, which leads to a contradiction with $|F'_\sus{1}\cap R_\sus{z^\calJ}|\ge 0.7|R_\sus{z^\calJ}|$, as we show at the end of the proof. Since the preprocessing and safe iterations increase $k$ by $\le 3d^2+(d+13)\sqrt{n}/3$ in total, and the preprocessing and unsafe iterations decrease $k$ by $\ge w/2$ in total, and since $k\ge 0$, we always have $w/2\le 3d^2+(d+13)\sqrt{n}/3$, which implies $w\le 0.02n$ since $d=0.01\sqrt{n}$.

A key issue is that to maintain the invariant $|F'_\sus{1}\cap R_\sus{z^\calJ}|\ge 0.7|R_\sus{z^\calJ}|$, we must consider the behavior of subrectangles with respect to $z^\calJ$, but to maintain the invariant $|z_\rightarrow|=0$, we must apply \autoref{lem:packing} with respect to $z$. Reconciling this involves a subtle back-and-forth between $R_z$ and $R_\sus{z^\calJ}$.

We now describe an iteration. Since $c_i\ne *$ for $\le w\le 0.02n$ many $i\le n/2$, and $z_i=0$ for $\le n/3$ many $i\le n/2$, we have $c_i=*$ and $z_i=1$ for $\ge n/2-0.02n-n/3\ge 0.1n$ many $i\le n/2$. Let $\calI$ be the set of all sets $I\subseteq\bracescolon{i\le n/2}{\text{$c_i=*$ and $z_i=1$}}$ with $|I|=\sqrt{n}$. We have $c_j\ne *$ for $\le w\le 0.02n$ many $j>n/2$, and $\calJ$ is the set of all sets $J\subseteq\bracescolon{j>n/2}{c_j=*}$ with $|J|=1$. Let $\calI\times\calJ=\bracescolon{I\cup J}{\text{$I\in\calI$ and $J\in\calJ$}}$. Note that $R_z\cup R_\sus{z^\calI}$ generally consists of invalid inputs (on which we know nothing a priori about $D$'s behavior), but $R_\sus{z^\calJ}\cup R_\sus{z^{\calI\times\calJ}}\subseteq F_1\subseteq F'_\sus{1}\cup F'_\sus{0}$.

Since $D$ is a $0.01$-error randomized protocol for $F'$, there exists a deterministic protocol $P$ in the support of $D$ such that $P(x,y)\ne F'(x,y)$ with probability $\le 0.01$ over $(x,y)$ sampled from the uniform mixture of the uniform distribution over $R_\sus{z^\calJ}$ and the uniform distribution over $R_\sus{z^{\calI\times\calJ}}$. Hence $P(x,y)\ne F'(x,y)$ for $\le 0.02|R_\sus{z^\calJ}|$ many $(x,y)\in R_\sus{z^\calJ}$ and for $\le 0.02|R_\sus{z^{\calI\times\calJ}}|$ many $(x,y)\in R_\sus{z^{\calI\times\calJ}}$. Let $P_1=P^{-1}(1)$ and $P_0=P^{-1}(0)$. Since $P$ has depth $d$, $P_1\cap R$ is partitioned into at most $2^d$ rectangles $R^1,R^2,R^3,\ldots{}$. Say $\ell$ is \emph{major} if $|R^\ell_\sus{z}|\ge 2^{-(d+4)}|R_z|$ and \emph{minor} otherwise. For each major $\ell$, we have $|R^\ell_\sus{z}|\ge 2^{-(k+d+4)}|S^{a,b}_\sus{z}|$, so by \autoref{lem:packing} (applied to the projections of $R^\ell$ and $z$ to the $*$ coordinates, with $m=n-w$), there exists a set $\calQ^\ell$ of pairwise disjoint subrectangles of $R^\ell$ such that $\sum_\sus{Q\in\calQ^\ell}|Q_z|\ge 0.99|R^\ell_\sus{z}|$ and for each $Q\in\calQ^\ell$ there exists a structure $(a',b',c')$ of width $w'$ extending $(a,b,c)$ such that $z$ agrees with $c'$, $Q$ is $(a',b',c')$-balanced, and $|Q_z|\ge 2^{-((k+d+4)+8-(w'-w))}|S^{a',b'}_\sus{z}|$. The latter bound implies $w'\le k+d+12+w\le 0.04n$. We have
\begin{align*}
\textstyle\sum_{\text{minor }\ell}|R^\ell_\sus{z}|~&\textstyle\le~2^d\cdot 2^{-(d+4)}|R_z|~\le~0.07|R_z|\\
\textstyle\sum_{\text{major }\ell}\bigparens{|R^\ell_\sus{z}|-\sum_\sus{Q\in\calQ^\ell}|Q_z|}~&\textstyle\le~\sum_{\text{major }\ell}0.01|R^\ell_\sus{z}|~\le~0.01|R_z|
\end{align*}
and thus, letting $\calQ=\bigcup_{\text{major }\ell}\calQ^\ell$:
\begin{equation} \label{eq:a}
\textstyle\sum_{Q\in\calQ}|Q_z|~=~|P_1\cap R_z|-\sum_{\text{minor }\ell}|R^\ell_\sus{z}|-\sum_{\text{major }\ell}\bigparens{|R^\ell_\sus{z}|-\sum_\sus{Q\in\calQ^\ell}|Q_z|}~\ge~|P_1\cap R_z|-0.08|R_z|\tag{$\star$}
\end{equation}
For each $Q\in\calQ$ with associated $(a',b',c')$ and $w'$, and for $J=\{j\}\in\calJ$, $z^J$ agrees with $c'$ iff $c'_\sus{j}=*$, which holds for $\ge n/2-w'\ge 0.92(n/2)\ge 0.92|\calJ|$ many $J\in\calJ$. If $z^J$ agrees with $c'$, then $|Q_\sus{z^J}|\ge 0.99|Q|/2^{n-w'}\ge 0.98|Q_z|$ since $z$ agrees with $c'$ and $Q$ is $(a',b',c')$-balanced. Thus:
\begin{equation} \label{eq:b}
\textstyle|Q_\sus{z^\calJ}|~=~\sum_{J\in\calJ}|Q_\sus{z^J}|~\ge~\sum_\sus{J\in\calJ\,:\,z^J\text{ agrees with }c'}|Q_\sus{z^J}|~\ge~0.92|\calJ|\cdot 0.98|Q_z|~\ge~0.9|\calJ|\cdot|Q_z|\tag{$\dagger$}
\end{equation}
It follows that: \[\textstyle|P_1\cap R_\sus{z^\calJ}|~\ge~\sum_{Q\in\calQ}|Q_\sus{z^\calJ}|~\ge~0.9|\calJ|\sum_{Q\in\calQ}|Q_z|~\ge~0.9|\calJ|\bigparens{|P_1\cap R_z|-0.08|R_z|}\] By the symmetry between outputting $1$ and outputting $0$, we also have: \[\textstyle|P_0\cap R_\sus{z^\calJ}|~\ge~0.9|\calJ|\bigparens{|P_0\cap R_z|-0.08|R_z|}\] We have $|R_z|\ge 0.99|R|/2^{n-w}\ge 0.98|R_\sus{z^J}|$ for each $J\in\calJ$ since $R$ is $(a,b,c)$-balanced, so:
\begin{equation} \label{eq:c}
\textstyle|R_z|~\ge~0.98\sum_{J\in\calJ}|R_\sus{z^J}|/|\calJ|~=~0.98|R_\sus{z^\calJ}|/|\calJ|\tag{$\ddagger$}
\end{equation}
It follows that \[\textstyle|P_0\cap R_\sus{z^\calJ}|~\ge~0.9|\calJ|\bigparens{|P_0\cap R_z|/|R_z|-0.08}|R_z|~\ge~0.8\bigparens{|P_0\cap R_z|/|R_z|-0.08}|R_\sus{z^\calJ}|\] and thus: \[\textstyle|F'_\sus{0}\cap R_\sus{z^\calJ}|~\ge~|P_0\cap R_\sus{z^\calJ}|-|F'_\sus{1}\cap P_0\cap R_\sus{z^\calJ}|~\ge~0.8\bigparens{|P_0\cap R_z|/|R_z|-0.08}|R_\sus{z^\calJ}|-0.02|R_\sus{z^\calJ}|\] The invariant $|F'_\sus{1}\cap R_\sus{z^\calJ}|\ge 0.7|R_\sus{z^\calJ}|$ implies $|F'_\sus{0}\cap R_\sus{z^\calJ}|\le 0.3|R_\sus{z^\calJ}|$, so combining yields: \[\textstyle 0.3~\ge~0.8\bigparens{|P_0\cap R_z|/|R_z|-0.08}-0.02~\ge~0.8|P_0\cap R_z|/|R_z|-0.1\] Rearranging then yields $|P_0\cap R_z|\le 0.5|R_z|$, so $|P_1\cap R_z|\ge 0.5|R_z|$. As we showed in \eqref{eq:a}, this implies \[\textstyle\sum_{Q\in\calQ}|Q_z|~\ge~|P_1\cap R_z|-0.08|R_z|~\ge~0.5|R_z|-0.08|R_z|~\ge~0.4|R_z|\] Say $Q\in\calQ$ is \emph{good} if $w'-w\le 3d$ (for the $w'$ associated with $Q$) and \emph{bad} otherwise. This iteration is \emph{safe} if $\sum_{\text{good }Q\in\calQ}|Q_z|\ge 0.2|R_z|$ and \emph{unsafe} otherwise, in which case $\sum_{\text{bad }Q\in\calQ}|Q_z|\ge 0.2|R_z|$.

\paragraph{Unsafe iteration:} As we showed in \eqref{eq:b} and \eqref{eq:c}: \[\textstyle\sum_{\text{bad }Q\in\calQ}|Q_\sus{z^\calJ}|~\ge~0.9|\calJ|\sum_{\text{bad }Q\in\calQ}|Q_z|~\ge~0.9|\calJ|\cdot 0.2|R_z|~\ge~0.9\cdot 0.2\cdot 0.98|R_\sus{z^\calJ}|~\ge~0.1|R_\sus{z^\calJ}|\] We have \[\textstyle\sum_{\text{bad }Q\in\calQ}|F'_\sus{0}\cap Q_\sus{z^\calJ}|~\le~|F'_\sus{0}\cap P_1\cap R_\sus{z^\calJ}|~\le~0.02|R_\sus{z^\calJ}|~\le~0.2\sum_{\text{bad }Q\in\calQ}|Q_\sus{z^\calJ}|\] so there exists a bad $Q\in\calQ$ with associated $(a',b',c')$ and $w'$ such that $|F'_\sus{0}\cap Q_\sus{z^\calJ}|\le 0.2|Q_\sus{z^\calJ}|\le 0.3|Q_\sus{z^\calJ}|$, so $|F'_\sus{1}\cap Q_\sus{z^\calJ}|\ge 0.7|Q_\sus{z^\calJ}|$. We conclude the iteration by updating $(a,b,c)\leftarrow(a',b',c')$ and $w\leftarrow w'$ and $R\leftarrow Q$ and $k\leftarrow k+d+12-(w'-w)$ and $\calJ\leftarrow\bigbracescolon{\{j\}}{\text{$j>n/2$ and $c'_\sus{j}=*$}}$. The invariants are maintained. As we wanted for an unsafe iteration, $z$ doesn't change and $k$ decreases by $(\text{increase in $w$})-d-12\ge(\text{increase in $w$})/2$ since $(\text{increase in $w$})>3d$ since $Q$ is bad.

\paragraph{Safe iteration:} For each good $Q\in\calQ$ with associated $(a',b',c')$ and $w'$, if we sample a uniformly random $I\in\calI$ and a uniformly random permutation of $I$'s elements, then{\allowdisplaybreaks
\begin{align*}
\textstyle\Pr[\text{$z^I$ doesn't agree with $c'$}]~&\textstyle=~\Pr\bigbrackets{(\exists i\in I):~c'_\sus{i}=1}\\*
&\textstyle=~\Pr\bigbrackets{(\exists i\,:\,\text{$c_i=*$ and $c'_\sus{i}=1$})~(\exists e\in[\sqrt{n}]):~\text{$I$'s $e$th element is $i$}}\\
&\textstyle\le~\sum_\sus{i\,:\,c_i=*\text{ and }c'_\sus{i}=1}\sum_\sus{e\in[\sqrt{n}]}\Pr[\text{$I$'s $e$th element is $i$}]\\
&\textstyle\le~(w'-w)\cdot\sqrt{n}\cdot 1/0.1n\\
&\textstyle\le~3d\cdot 10/\sqrt{n}\\*
