The syndrome $W+H\hat{X}_A$ remaining after the correction $\hat{X}_A$ has
\begin{align}
\rs(W+H\hat{X}_A) &\subset \Bc_\ell(\rs(W))\backslash\Bp(\Ac_\ell(\rs(W)))\\
\cs(W+H\hat{X}_A) &\subset \cs(W)
\end{align}
\end{lemma}

\begin{proof}
First, $\rs(\hat{X}_A) \subset \Ac_\ell(\rs(W))$, so $\rs(H\hat{X}_A)\subset \Bc_\ell(\rs(W))$; in addition, $\rs(W) \subset \Bc_\ell(\rs(W))$, so $\rs(W+H\hat{X}_A)$ is a subset of $\Bc_\ell(\rs(W))$. Next, note that Lemma \ref{lemma:applying_the_inverse_of_a_submatrix_is_equivalent_to_solving_a_linear_system} implies that the rows of $W+H\hat{X}_A$ indexed by $\Bp(\Ac_\ell(\rs(W))$ are zero. Finally, $\cs(\hat{X}_A)\subset\cs(W)$ implies $\cs(W+H\hat{X}_A)\subset\cs(W)$. 
\end{proof}

\subsubsection{The second correction}\label{sec:the_second_correction}

The final step of the proof of Proposition \ref{prop:output_is_correct} is:

\begin{lemma}\label{lemma:b_side_correction_equals_remaining_error}
$\hat{X}_B=X_B''$.
\end{lemma}

\begin{proof}
\begin{align}
\hat{X}_B &=(H\hat{X}_A+W)\esubmi{H}{\Ap(\Bc_\ell(\cs(W)))}{\Bc_\ell(\cs(W))} \\
&= X_B''H\esubmi{H}{\Ap(\Bc_\ell(\cs(W)))}{\Bc_\ell(\cs(W))} \\
&= X_B'' \twobytwo{\subm{I}{\Bc_\ell(\cs(W))}{\Bc_\ell(\cs(W))}}{0}{H''}{0} \\
&=X_B''
\end{align}
where $H''=\subm{H}{B\backslash\Bc_\ell(\cs(W))}{\Ap(\Bc_\ell(\cs(W)))}\submi{H}{\Ap(\Bc_\ell(\cs(W)))}{\Bc_\ell(\cs(W))}$. The last step is because the column support of $X_B''$ is a subset of $\Bcu_D(\cs(W))$, which is included in $\Bc_\ell(\cs(W))$.
\end{proof}

\subsection{Proof of Proposition \ref{prop:linear_time}: linear time and logarithmic depth}\label{sec:proof_of_linear_time}

\subsubsection{Computing the row and column support of the syndrome}

\begin{lemma}\label{lemma:computation_of_the_row_and_column_support_of_the_syndrome}
The row and column support of any $W \in \F^{B\times A}$ can be computed in time $O(|A||B|)$ in the uniform cost model or by a circuit of depth $O(\log|A|+\log|B|)$ with $O(|A||B|)$ gates. 
\end{lemma}

\begin{proof}
The sequential algorithm: for $b \in B$, for $a\in A$, if $W_{b,a}=1$, add $a$ to $\cs(W)$ and add $b$ to $\rs(W)$. 

The parallel algorithm: whether a row of $W$ is not zero can be computed by a binary tree of OR gates, so the depth is $O(\log|A|)$ and the number of gates is $O(|A|)$ per row. Similarly, whether a column of $W$ is not zero can be computed by a binary tree of OR gates with depth $O(\log|B|)$ and with $O(|B|)$ gates per column. 
\end{proof}

